1	<?php
2	
3	/* Quality Test Maintenance */
4	
5	require(__DIR__ . '/includes/session.php');
6	
7	$Title = __('Update Related Items');
8	$ViewTopic = 'QualityAssurance';
9	$BookMark = 'QA_Tests';
10	include('includes/header.php');
11	
12	echo '<a href="' . $RootPath . '/SelectProduct.php" class="toplink">' . __('Back to Items') . '</a>';
13	
14	echo '<p class="page_title_text"><img alt="" src="', $RootPath, '/css/', $Theme,
15		'/images/inventory.png" title="', // Icon image.
16		$Title, '" /> ', // Icon title.
17		$Title, '</p>';// Page title.
18	
19	include('includes/SQL_CommonFunctions.php');
20	
21	//initialise no input errors assumed initially before we test
22	$InputError = 0;
23	
24	if (isset($_GET['Item'])){
25		$Item = trim(mb_strtoupper($_GET['Item']));
26	} elseif (isset($_POST['Item'])){
27		$Item = trim(mb_strtoupper($_POST['Item']));
28	}
29	if (isset($_GET['Related'])){
30		$Related = trim(mb_strtoupper($_GET['Related']));
31	} elseif (isset($_POST['Related'])){
32		$Related = trim(mb_strtoupper($_POST['Related']));
33	}
34	
35	$Result = DB_query("SELECT stockmaster.description
36						FROM stockmaster
37						WHERE stockmaster.stockid='".$Item."'");
38	$MyRow = DB_fetch_row($Result);
39	
40	if (DB_num_rows($Result)==0){
41		prnMsg( __('The part code entered does not exist in the database') . ': ' . $Item . __('Only valid parts can have related items entered against them'),'error');
42		$InputError=1;
43	}
44	
45	
46	if (!isset($Item)){
47		echo '<p>';
48		prnMsg(__('An item must first be selected before this page is called') . '. ' . __('The product selection page should call this page with a valid product code'),'error');
49		include('includes/footer.php');
50		exit();
51	}
52	
53	$PartDescription = $MyRow[0];
54	
55	if (isset($_POST['submit'])) {
56	
57		/* actions to take once the user has clicked the submit button
58		ie the page has called itself with some user input */
59	
60		//first off validate inputs sensible
61	
62		$Result_related = DB_query("SELECT stockmaster.description,
63								stockmaster.mbflag
64						FROM stockmaster
65						WHERE stockmaster.stockid='".$_POST['Related']."'");
66		$MyRow_related = DB_fetch_row($Result_related);
67	
68		if (DB_num_rows($Result_related)==0){
69			prnMsg( __('The part code entered as related item does not exist in the database') . ': ' . $_POST['Related'] .  __('Only valid parts can be related items'),'error');
70			$InputError=1;
71		}
72	
73		$SQL = "SELECT related
74					FROM relateditems
75				WHERE stockid='".$Item."'
76					AND related = '" . $_POST['Related'] . "'";
77		$Result = DB_query($SQL);
78		$MyRow = DB_fetch_row($Result);
79	
80		if (DB_num_rows($Result)!=0){
81			prnMsg( __('This related item has already been entered.') , 'warn');
82			$InputError =1;
83		}
84	
85		if ($_POST['Related'] == $Item){
86			prnMsg( __('An item can not be related to itself') , 'warn');
87			$InputError =1;
88		}
89	
90		if ($InputError !=1) {
91			$SQL = "INSERT INTO relateditems (stockid,
92										related)
93								VALUES ('" . $Item . "',
94									'" . $_POST['Related'] . "')";
95			$ErrMsg = __('The new related item could not be added');
96			$Result = DB_query($SQL, $ErrMsg);
97	
98			prnMsg($_POST['Related'] . ' ' . __('is now related to') . ' ' . $Item,'success');
99	
100			/* It is safe to assume that, if A is related to B, B is related to A */
101			$SQL_reverse = "SELECT related
102						FROM relateditems
103					WHERE stockid='".$_POST['Related']."'
104						AND related = '" . $Item . "'";
105			$Result_reverse = DB_query($SQL_reverse);
106			$MyRow_reverse = DB_fetch_row($Result_reverse);
107	
108			if (DB_num_rows($Result_reverse)==0){
109				$SQL = "INSERT INTO relateditems (stockid,
110											related)
111									VALUES ('" . $_POST['Related'] . "',
112										'" . $Item . "')";
113				$ErrMsg = __('The new related item could not be added');
114				$Result = DB_query($SQL, $ErrMsg);
115				prnMsg($Item . ' ' . __('is now related to') . ' ' . $_POST['Related'],'success');
116			}
117		}
118	
119		unset($_POST['Related']);
120	
121	} elseif (isset($_GET['delete'])) {
122	//the link to delete a selected record was clicked instead of the submit button
123	
124		/* Again it is safe to assume that we have to delete both relations A to B and B to A */
125	
